def compute(vars):
    cash_equivalents = vars["Cash Equivalents"]
    marketable_securities = vars["Short-term Investments"]
    accounts_receivable = vars["Accounts Receivable"]
    current_liabilities = vars["Current Liabilities"]

    if current_liabilities == 0:
        return None

    quick_ratio = (
        cash_equivalents
        + marketable_securities
        + accounts_receivable
    ) / current_liabilities

    return {
        "value": quick_ratio,
        "trace": {
            "Cash Equivalents": cash_equivalents,
            "Short-term Investments": marketable_securities,
            "Accounts Receivable": accounts_receivable,
            "Current Liabilities": current_liabilities,
            "Quick Assets": (
                cash_equivalents
                + marketable_securities
                + accounts_receivable
            ),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
